import { View, TextInput, StyleSheet } from "react-native";
import { useState } from "react";
import { registerRootComponent } from "expo";

function App() {
  const [text, setText] = useState("");
  const [focused, setFocused] = useState(false);
  return (
    <View style={styles.screen}>
      <TextInput nativeID="field" style={[styles.input, focused && styles.active]} placeholder="Хайх бараа..."
        value={text} onChangeText={setText}
        onFocus={() => setFocused(true)} onBlur={() => setFocused(false)} />
    </View>
  );
}

const styles = StyleSheet.create({
  screen: { flex: 1, padding: 24, justifyContent: "center" },
  input: { borderWidth: 2, borderColor: "#cbd5e1", borderRadius: 10, padding: 14 },
  active: { borderColor: "#2563eb" },
});

registerRootComponent(App);
